function Exercise1({ lang, t }) {
  const [ans,setAns]=useState({q1:"",q2:"",q3:""});
  const [showC,setShowC]=useState(false);
  const qs={
    fr:[
      {id:"q1",q:"LMAA = ? (Répondre : les 4 mots en anglais)",correct:"London Maritime Arbitrators Association"},
      {id:"q2",q:"Convention permettant d'exécuter une sentence arbitrale dans 156 États ?\n(Répondre : ville + année)",correct:"New York 1958"},
      {id:"q3",q:"Prescription pour les litiges cargo (Règles Haye-Visby) ?\n(Répondre : le délai)",correct:"1 an"},
    ],
    en:[
      {id:"q1",q:"LMAA = ? (Answer: the 4 words)",correct:"London Maritime Arbitrators Association"},
      {id:"q2",q:"Convention allowing enforcement of an arbitral award in 156 states?\n(Answer: city + year)",correct:"New York 1958"},
      {id:"q3",q:"Prescription for cargo disputes (Hague-Visby Rules)?\n(Answer: the time limit)",correct:"1 year"},
    ],
    es:[
      {id:"q1",q:"LMAA = ? (Responder: las 4 palabras en inglés)",correct:"London Maritime Arbitrators Association"},
      {id:"q2",q:"¿Convenio que permite ejecutar un laudo arbitral en 156 Estados?\n(Responder: ciudad + año)",correct:"Nueva York 1958"},
      {id:"q3",q:"¿Prescripción para los litigios de carga (Reglas La Haya-Visby)?\n(Responder: el plazo)",correct:"1 año"},
    ],
    pt:[
      {id:"q1",q:"LMAA = ? (Responder: as 4 palavras em inglês)",correct:"London Maritime Arbitrators Association"},
      {id:"q2",q:"Convenção que permite executar uma sentença arbitral em 156 estados?\n(Responder: cidade + ano)",correct:"Nova Iorque 1958"},
      {id:"q3",q:"Prescrição para litígios de carga (Regras Haia-Visby)?\n(Responder: o prazo)",correct:"1 ano"},
    ],
  };
  const list=qs[lang]||qs.fr;
  const chk=(q,val)=>{
    const v=val.trim().toLowerCase();
    if(q.id==="q1") return v.includes("london")&&v.includes("maritime")&&v.includes("arbitrat");
    if(q.id==="q2") return (v.includes("new york")||v.includes("nueva york")||v.includes("nova iorque"))&&v.includes("1958");
    if(q.id==="q3") return v.includes("1 an")||v.includes("1 year")||v.includes("1 año")||v.includes("1 ano");
    return false;
  };
  return(
    <div>
      <div style={{background:"rgba(0,0,0,0.4)",borderRadius:12,padding:"10px 12px",marginBottom:12,border:`1px solid ${C.gold}44`,fontSize:11,color:C.gold2,lineHeight:1.6}}>
        {lang==="fr"?"💡 Rappels : LMAA = London Maritime Arbitrators Association · Convention New York 1958 = 156 États · Haye-Visby = 1 an pour cargaison"
        :lang==="en"?"💡 Reminders: LMAA = London Maritime Arbitrators Association · New York Convention 1958 = 156 states · Hague-Visby = 1 year for cargo"
        :lang==="es"?"💡 Recordatorios: LMAA = London Maritime Arbitrators Association · Convenio Nueva York 1958 = 156 Estados · La Haya-Visby = 1 año para carga"
        :"💡 Lembretes: LMAA = London Maritime Arbitrators Association · Convenção Nova Iorque 1958 = 156 estados · Haia-Visby = 1 ano para carga"}
      </div>
      {list.map((q,i)=>(
        <div key={q.id} style={{marginBottom:12}}>
          <div style={{fontSize:12,color:C.white,marginBottom:6,lineHeight:1.5,whiteSpace:"pre-line",fontWeight:600}}>{i+1}. {q.q}</div>
          <input type="text" value={ans[q.id]} onChange={e=>setAns(a=>({...a,[q.id]:e.target.value}))} placeholder="?"
            style={{width:"100%",padding:"10px",borderRadius:10,background:"rgba(255,255,255,0.07)",border:`1px solid ${showC?(chk(q,ans[q.id])?C.green:C.red):C.border}`,color:C.white,fontSize:13,fontFamily:"monospace",fontWeight:700,textAlign:"center",boxSizing:"border-box"}}/>
          {showC&&<div style={{fontSize:11,marginTop:4,fontWeight:600,color:chk(q,ans[q.id])?C.green:C.red}}>{chk(q,ans[q.id])?"✓":`✗ → ${q.correct}`}</div>}
        </div>
      ))}
      {showC&&<div style={{padding:"12px",borderRadius:12,background:"rgba(30,138,74,0.1)",border:`1px solid ${C.green}44`,fontSize:11,color:C.white,lineHeight:1.7,marginBottom:10}}>
        {lang==="fr"?"✅ Q1: London Maritime Arbitrators Association (leader mondial arbitrage maritime)\n✅ Q2: Convention de New York 1958 (156 États · sentences arbitrales exécutoires directement)\n✅ Q3: 1 an (Règles de La Haye-Visby · à compter de la livraison)"
        :lang==="en"?"✅ Q1: London Maritime Arbitrators Association (global maritime arbitration leader)\n✅ Q2: New York Convention 1958 (156 states · arbitral awards directly enforceable)\n✅ Q3: 1 year (Hague-Visby Rules · from delivery date)"
        :"✅ Q1: London Maritime Arbitrators Association · Q2: Convenio Nueva York 1958 · Q3: 1 año"}
      </div>}
      <button onClick={()=>setShowC(v=>!v)} style={{width:"100%",padding:"11px 0",borderRadius:12,background:showC?"rgba(30,138,74,0.2)":"rgba(201,146,42,0.15)",border:`1px solid ${showC?C.green:C.gold}44`,color:showC?C.green:C.gold2,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"'Cinzel',serif"}}>
        {showC?t.hideCorr:t.showCorr}
      </button>
    </div>
  );
}

